// Entry point copied verbatim into every program generated by RecompRadar.
using System.Globalization;
using System.Reflection;
using System.Text;
using System.Text.Json;

namespace RecompRadar.Generated;

internal static class Program
{
    private const int ExitFault = 70;
    private const int ExitStopped = 71;
    private const int ExitStepLimit = 72;
    private const int ExitUsage = 64;

    private static int Main(string[] args)
    {
        long limit = long.MaxValue;
        string? reportPath = null;
        for (var i = 0; i < args.Length; i++)
        {
            switch (args[i])
            {
                case "--max-instructions" when i + 1 < args.Length && long.TryParse(args[i + 1], NumberStyles.None, CultureInfo.InvariantCulture, out limit) && limit > 0:
                    i++;
                    break;
                case "--report" when i + 1 < args.Length:
                    reportPath = args[++i];
                    break;
                case "--info":
                    Console.WriteLine(BuildInfo.Description);
                    return 0;
                default:
                    Console.Error.WriteLine("Usage: <program> [--max-instructions <n>] [--report <file.json>] [--info]");
                    return ExitUsage;
            }
        }

        using var stdout = new StreamWriter(Console.OpenStandardOutput(), new UTF8Encoding(false), 4096) { AutoFlush = false };
        using var image = Assembly.GetExecutingAssembly().GetManifestResourceStream("image.bin")
                          ?? throw new InvalidOperationException("The program image resource is missing.");
        var memory = new GuestMemory(image, out var entry);
        var cpu = new Cpu(memory, stdout) { Limit = limit };

        string status;
        int exitCode;
        string? message = null;
        try
        {
            Recompiled.Run(cpu, entry);
            status = "Faulted";
            exitCode = ExitFault;
            message = "The dispatcher returned unexpectedly.";
        }
        catch (ProgramExitException exit)
        {
            status = "Exited";
            exitCode = exit.ExitCode;
        }
        catch (GuestFaultException fault)
        {
            status = "Faulted";
            exitCode = ExitFault;
            message = fault.Message;
        }
        catch (ProgramStopException stop)
        {
            status = "Stopped";
            exitCode = ExitStopped;
            message = stop.Message;
        }
        catch (StepLimitException limitReached)
        {
            status = "StepLimitReached";
            exitCode = ExitStepLimit;
            message = limitReached.Message;
        }

        stdout.Flush();
        if (message is not null)
        {
            Console.Error.WriteLine($"[{status}] {message}");
        }

        if (reportPath is not null)
        {
            WriteReport(reportPath, status, exitCode, message, cpu);
        }

        return exitCode;
    }

    private static void WriteReport(string path, string status, int exitCode, string? message, Cpu cpu)
    {
        using var stream = File.Create(path);
        using var json = new Utf8JsonWriter(stream, new JsonWriterOptions { Indented = true });
        json.WriteStartObject();
        json.WriteString("status", status);
        json.WriteNumber("exitCode", exitCode);
        json.WriteNumber("instructionsExecuted", cpu.Executed);
        if (message is null)
        {
            json.WriteNull("message");
        }
        else
        {
            json.WriteString("message", message);
        }

        json.WriteString("output", cpu.Output);
        json.WriteStartArray("registers");
        foreach (var value in cpu.R)
        {
            json.WriteNumberValue(value);
        }

        json.WriteEndArray();
        json.WriteEndObject();
    }
}
